def block_stat(grid, pr, pc, stat):
    out = np.zeros((3,3), dtype=int)
    g = np.array(grid)
    for i,(r0,r1) in enumerate(bands(pr)):
        for j,(c0,c1) in enumerate(bands(pc)):
            B = g[r0:r1, c0:c1]
            if stat[0]=='count':
                out[i,j] = int((B==stat[1]).sum())
            elif stat[0]=='ne':
                out[i,j] = int((B!=stat[1]).sum())
            elif stat[0]=='ge':
                out[i,j] = int((B>=stat[1]).sum())
            elif stat[0]=='le':
                out[i,j] = int((B<=stat[1]).sum())
            elif stat[0]=='sum':
                out[i,j] = int(B.sum())
            elif stat[0]=='dist':
                out[i,j] = len(set(B.flatten().tolist()))
    return out

