def bstat(B, stat):
    if stat[0]=='count': return int((B==stat[1]).sum())
    if stat[0]=='ne': return int((B!=stat[1]).sum())
    if stat[0]=='ge': return int((B>=stat[1]).sum())
    if stat[0]=='le': return int((B<=stat[1]).sum())
    if stat[0]=='sum': return int(B.sum())
    if stat[0]=='dist': return len(set(B.flatten().tolist()))

def colband_stats(grid, pc, stat):
    g = np.array(grid); C=[]
    for (c0,c1) in bands(pc):
        B = g[:, c0:c1]
        C.append(bstat(B, stat))
    return C

