                          'rowmin': lambda S: S==S.min(axis=1, keepdims=True),
                          'colmin': lambda S: S==S.min(axis=0, keepdims=True)}.items():
                ok=True
                for k in G:
                    try:
                        if not np.array_equal(cf(SG[k][name]), T[k]): ok=False; break
                    except Exception: ok=False; break
                if ok: hits.append((pr,pc,name,cn))
print(hits, len(hits), time.time()-t0)
